import * as THREE from 'three';
import {createHold,holdDefinition,disposeHold} from './holds.js';
import {nearestSocket} from './bolt-grid.js';

// Pointer edits are expressed in the selected wall's local plane. Camera orbit
// receives beta/explore drags, including drags that begin over a hold.
export function createHoldEditor({scene,camera,renderer,controls,sectors,walls,holds,defs,state,select,onPlace,onBeta,history,sync,onRemove}){
 const canvas=renderer.domElement,ray=new THREE.Raycaster(),pointer=new THREE.Vector2();
 let pendingBeta=null;
 let lastPointer=null,gesture=null,ghost=null,ghostKey='',candidate=null;
 const gizmo=new THREE.Group();gizmo.visible=false;scene.add(gizmo);
 const ink=new THREE.MeshBasicMaterial({color:'#e9845d',depthTest:false,depthWrite:false});
 const ivory=new THREE.MeshBasicMaterial({color:'#fff7df',depthTest:false,depthWrite:false});
 const ring=new THREE.Mesh(new THREE.TorusGeometry(1,.018,8,128),ink);ring.userData.action='rotate';gizmo.add(ring);
 const knob=new THREE.Mesh(new THREE.SphereGeometry(.105,16,12),ivory);knob.userData.action='rotate';gizmo.add(knob);
 const scaleKnob=new THREE.Mesh(new THREE.BoxGeometry(.20,.20,.06),ivory);scaleKnob.userData.action='scale';gizmo.add(scaleKnob);
 const ringHit=new THREE.Mesh(new THREE.TorusGeometry(1,.065,8,96),new THREE.MeshBasicMaterial({visible:false}));ringHit.userData.action='rotate';gizmo.add(ringHit);
 gizmo.traverse(o=>o.renderOrder=1000);
 const hint=document.querySelector('#placementHint'),badge=document.querySelector('#selectionBadge'),actions=document.querySelector('#selectionActions');
 document.querySelector('#deleteSelected').onclick=onRemove;document.querySelector('#deselectHold').onclick=()=>select(null);
 const ghostMaterials=[];
 function cast(e,objects){const r=canvas.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(pointer,camera);return ray.intersectObjects(objects,false)}
 function planePoint(e,si,z=.132){cast(e,[]);const face=sectors[si].face;face.updateWorldMatrix(true,false);const n=new THREE.Vector3(0,0,1).transformDirection(face.matrixWorld),origin=face.localToWorld(new THREE.Vector3(0,0,z));const p=ray.ray.intersectPlane(new THREE.Plane().setFromNormalAndCoplanarPoint(n,origin),new THREE.Vector3());return p?face.worldToLocal(p):null}
 function bounded(si,p,geometry,size=1,rotation=0){geometry.computeBoundingBox();const b=geometry.boundingBox;let minX=Infinity,maxX=-Infinity,minY=Infinity,maxY=-Infinity;for(const x of [b.min.x,b.max.x])for(const y of [b.min.y,b.max.y]){const xx=(x*Math.cos(rotation)-y*Math.sin(rotation))*size,yy=(x*Math.sin(rotation)+y*Math.cos(rotation))*size;minX=Math.min(minX,xx);maxX=Math.max(maxX,xx);minY=Math.min(minY,yy);maxY=Math.max(maxY,yy)}return new THREE.Vector3(THREE.MathUtils.clamp(p.x,-sectors[si].width/2-minX+.015,sectors[si].width/2-maxX-.015),THREE.MathUtils.clamp(p.y,-minY+.015,defs[si].h-maxY-.015),.132)}
 function clearGhost(){if(ghost){ghost.parent?.remove(ghost);const footprint=ghost.getObjectByName('footprint');if(footprint)ghost.remove(footprint);disposeHold(ghost);ghost=null}for(const m of ghostMaterials)m.dispose();ghostMaterials.length=0;ghostKey=''}
 function updateGhost(){const s=state();document.body.classList.toggle('placing',s.placing);candidate=null;if(!s.placing||s.mode!=='set'||gesture||!lastPointer||document.elementFromPoint(lastPointer.clientX,lastPointer.clientY)!==canvas){if(ghost)ghost.visible=false;hint.hidden=true;return}
  const key=s.type+s.color;if(key!==ghostKey){clearGhost();ghost=createHold(s.type,s.color);ghostKey=key;ghost.material.forEach(m=>{m.transparent=true;m.opacity=.40;m.depthWrite=false;m.emissive.set('#274d37');m.emissiveIntensity=.3});ghost.traverse(o=>o.castShadow=false);ghost.children.forEach(c=>c.visible=false);
   // Flatten the same mesh into a footprint: this follows the hold's true outline.
   const shadowMaterial=new THREE.MeshBasicMaterial({color:'#254735',transparent:true,opacity:.27,depthWrite:false,side:THREE.DoubleSide});ghostMaterials.push(shadowMaterial);const footprint=new THREE.Mesh(ghost.geometry,shadowMaterial);footprint.name='footprint';footprint.scale.z=.001;footprint.position.z=-.003;ghost.add(footprint);const socketMaterial=new THREE.MeshBasicMaterial({color:'#e79c58',depthTest:false});ghostMaterials.push(socketMaterial);const socketRing=new THREE.Mesh(new THREE.RingGeometry(.027,.037,32),socketMaterial);socketRing.position.z=.014;ghost.add(socketRing);
  }
  const hit=cast(lastPointer,walls).find(h=>h.face.normal.z>.9);if(!hit){ghost.visible=false;hint.hidden=true;return}const si=hit.object.userData.sector,face=sectors[si].face,p=face.worldToLocal(hit.point.clone());const socket=nearestSocket(sectors,holds,si,p,ghost,true);if(!socket){ghost.visible=false;hint.hidden=false;hint.textContent='This socket is occupied, covered by a volume, or too close to the panel edge. Choose another hole.';return;}const pos=socket.position;face.add(ghost);ghost.position.copy(pos);ghost.visible=true;candidate={si,pos};hint.hidden=false;hint.textContent=`${holdDefinition(s.type).name} · Snapped to bolt hole · Click to place · Shift to keep placing · Esc to cancel`;hint.dataset.position=`${pos.x.toFixed(3)},${pos.y.toFixed(3)}`;
 }
 function updateGizmo(){const s=state(),h=s.selected;if(!h||s.placing||s.mode==='beta'){gizmo.visible=false;badge.hidden=true;actions.hidden=true;return}
  const face=sectors[h.userData.si].face;face.updateWorldMatrix(true,false);const normal=new THREE.Vector3(0,0,1).transformDirection(face.matrixWorld);const pos=face.localToWorld(h.position.clone());if(normal.dot(camera.position.clone().sub(pos))<=0){gizmo.visible=false;badge.hidden=true;actions.hidden=true;return}
  face.add(gizmo);gizmo.position.copy(h.position);gizmo.position.z+=holdDefinition(h.userData.type).d*h.userData.size+.035;gizmo.rotation.z=0;
  h.geometry.computeBoundingBox();const b=h.geometry.boundingBox;const size=Math.max(Math.abs(b.min.x),Math.abs(b.max.x),Math.abs(b.min.y),Math.abs(b.max.y))*h.userData.size;
  const worldPerPixel=2*camera.position.distanceTo(pos)*Math.tan(THREE.MathUtils.degToRad(camera.fov/2))/canvas.clientHeight;
  const radius=Math.max(size+.08,worldPerPixel*45);gizmo.scale.setScalar(radius);knob.position.set(Math.cos(h.rotation.z),Math.sin(h.rotation.z),.01);scaleKnob.position.set(.707,-.707,.01);gizmo.visible=true;
  const screen=face.localToWorld(new THREE.Vector3(h.position.x,h.position.y+radius+.1,gizmo.position.z)).project(camera);badge.hidden=screen.z>1;badge.style.left=((screen.x+1)/2*canvas.clientWidth)+'px';badge.style.top=((1-screen.y)/2*canvas.clientHeight)+'px';badge.textContent=`${Math.round(THREE.MathUtils.radToDeg(h.rotation.z))}° · ${h.userData.size.toFixed(1)}×`;badge.dataset.rotation=h.rotation.z.toFixed(4);const bottom=face.localToWorld(new THREE.Vector3(h.position.x,h.position.y-radius-.10,gizmo.position.z)).project(camera);actions.hidden=badge.hidden;actions.style.left=((bottom.x+1)/2*canvas.clientWidth)+'px';actions.style.top=((1-bottom.y)/2*canvas.clientHeight)+'px';
 }
 function intercept(e){e.preventDefault();e.stopImmediatePropagation()}
 function endGesture(cancel=false){if(!gesture)return;const g=gesture;gesture=null;if(cancel&&g.hold){g.hold.position.copy(g.startPosition);g.hold.rotation.z=g.startRotation;g.hold.scale.setScalar(g.startSize);Object.assign(g.hold.userData,{x:g.startPosition.x,y:g.startPosition.y,rotation:g.startRotation,size:g.startSize});sync()}controls.enabled=true;if(canvas.hasPointerCapture(g.pointerId))canvas.releasePointerCapture(g.pointerId);canvas.style.cursor='';updateGizmo()}
 function startGesture(e,action,h){const p=planePoint(e,h.userData.si,action==='move'?.132:gizmo.position.z);if(!p)return;gesture={action,hold:h,pointerId:e.pointerId,clientX:e.clientX,clientY:e.clientY,startPoint:p,startPosition:h.position.clone(),startRotation:h.rotation.z,startSize:h.userData.size,previousAngle:Math.atan2(p.y-h.position.y,p.x-h.position.x),accumulated:0,changed:false};controls.enabled=false;camera.updateMatrixWorld();canvas.setPointerCapture(e.pointerId);canvas.style.cursor=action==='move'?'grabbing':action==='scale'?'nwse-resize':'grabbing';intercept(e)}
 canvas.addEventListener('pointerdown',e=>{if(e.isPrimary===false){pendingBeta=null;return;}if(e.button!==0||state().blocked)return;lastPointer={clientX:e.clientX,clientY:e.clientY};const s=state();if(s.placing&&s.mode==='set'){updateGhost();gesture={action:'place',pointerId:e.pointerId,clientX:e.clientX,clientY:e.clientY};controls.enabled=false;canvas.setPointerCapture(e.pointerId);intercept(e);return}
  if(s.selected&&gizmo.visible){const handle=cast(e,[scaleKnob,knob,ringHit])[0];if(handle){startGesture(e,handle.object.userData.action,s.selected);return}}
  const hit=cast(e,holds)[0];if(hit){if(s.mode==='beta'||s.mode==='explore'){pendingBeta={hold:hit.object,id:e.pointerId,x:e.clientX,y:e.clientY,moved:false};return}select(hit.object);updateGizmo();startGesture(e,'move',hit.object);return}
  if(s.mode!=='beta')select(null);
 },{capture:true});
 canvas.addEventListener('pointermove',e=>{if(pendingBeta&&e.pointerId===pendingBeta.id&&Math.hypot(e.clientX-pendingBeta.x,e.clientY-pendingBeta.y)>5)pendingBeta.moved=true;if(state().blocked)return;lastPointer={clientX:e.clientX,clientY:e.clientY};if(!gesture){if(e.buttons){canvas.style.cursor='grabbing';return;}updateGhost();const s=state();if(!s.placing){const handle=gizmo.visible&&cast(e,[scaleKnob,knob,ringHit])[0];canvas.style.cursor=handle?(handle.object===scaleKnob?'nwse-resize':'grab'):cast(e,holds)[0]?'grab':''}return}
  intercept(e);const g=gesture;if(g.action==='place'){const keep=gesture;gesture=null;updateGhost();gesture=keep;return}if(Math.hypot(e.clientX-g.clientX,e.clientY-g.clientY)<3&&!g.changed)return;
  const h=g.hold,p=planePoint(e,h.userData.si,g.action==='move'?.132:gizmo.position.z);if(!p)return;if(!g.changed){history();g.changed=true}
  if(g.action==='move'){const desired=g.startPosition.clone().add(p.clone().sub(g.startPoint));const socket=nearestSocket(sectors,holds,h.userData.si,desired,h,true);if(!socket)return;h.position.copy(socket.position);h.userData.socket=socket.id;h.userData.x=h.position.x;h.userData.y=h.position.y}
  if(g.action==='rotate'){const a=Math.atan2(p.y-h.position.y,p.x-h.position.x);g.accumulated+=Math.atan2(Math.sin(a-g.previousAngle),Math.cos(a-g.previousAngle));g.previousAngle=a;let angle=g.startRotation+g.accumulated;if(e.shiftKey)angle=Math.round(angle/(Math.PI/12))*(Math.PI/12);h.rotation.z=angle;h.userData.rotation=angle}
  if(g.action==='scale'){const initial=g.startPoint.distanceTo(new THREE.Vector3(g.startPosition.x,g.startPosition.y,g.startPoint.z));const current=p.distanceTo(new THREE.Vector3(h.position.x,h.position.y,p.z));const size=THREE.MathUtils.clamp(g.startSize*current/Math.max(.01,initial),.5,2.3);h.scale.setScalar(size);h.userData.size=size}
  sync();updateGizmo();
 },{capture:true});
 canvas.addEventListener('pointerup',e=>{if(pendingBeta&&e.pointerId===pendingBeta.id){const pick=pendingBeta;pendingBeta=null;if(!pick.moved&&!state().blocked&&Math.hypot(e.clientX-pick.x,e.clientY-pick.y)<=5&&cast(e,holds)[0]?.object===pick.hold)queueMicrotask(()=>onBeta(pick.hold));}if(!gesture||e.pointerId!==gesture.pointerId)return;const g=gesture;intercept(e);if(g.action==='place'){gesture=null;lastPointer={clientX:e.clientX,clientY:e.clientY};updateGhost();if(candidate){history();onPlace(candidate.si,candidate.pos.clone(),e.shiftKey)}controls.enabled=true;if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);updateGhost();updateGizmo();return}endGesture()}, {capture:true});
 canvas.addEventListener('pointercancel',()=>{pendingBeta=null;endGesture(true);});canvas.addEventListener('lostpointercapture',()=>{pendingBeta=null;if(gesture)endGesture(true)});canvas.addEventListener('pointerleave',()=>{if(!gesture){lastPointer=null;updateGhost()}});window.addEventListener('blur',()=>{pendingBeta=null;endGesture(true);lastPointer=null;updateGhost()});
 return{update(){updateGhost();updateGizmo()},cancel(){pendingBeta=null;endGesture(true);lastPointer=null;updateGhost();updateGizmo()},remove:onRemove};
}
